package analysis

import (
	"fmt"
	"io"
	"sort"
)

type phase struct {
	from, to int
	label    string
}

var phases = []phase{{0, 6, "opening, 0-6 min"}, {6, 12, "middle, 6-12 min"}, {12, 99, "late, 12+ min"}}

// Playbook writes what strong players build and when, from replay logs, as markdown
// (docs/research/pro-playbook.md, regenerated by make benchmarks).
func Playbook(w io.Writer, games []*Recorded, b *Benchmark) {
	players := 0
	for _, g := range games {
		players += len(g.Teams)
	}
	if players == 0 {
		fmt.Fprintln(w, "No games.")
		return
	}
	fmt.Fprintf(w, "# Strong players' playbook\n\nGenerated by `make benchmarks` from %d replays (%d players) of %s. Numbers are per player.\n", b.Games, b.Players, b.Description)

	fmt.Fprint(w, "\n## Economy by minute\n\nMedian (lower-upper quartile).\n\n")
	cols := []string{"metalIncome", "energyIncome", "mex", "generators", "factories", "builders", "army", "turrets"}
	fmt.Fprint(w, "| Minute |")
	for _, c := range cols {
		fmt.Fprintf(w, " %s |", MetricNames[c])
	}
	fmt.Fprint(w, "\n|---|")
	for range cols {
		fmt.Fprint(w, "---|")
	}
	fmt.Fprintln(w)
	for _, minute := range []int{2, 3, 4, 5, 6, 8, 10, 12, 15, 18, 20, 25} {
		if _, ok := b.Band(minute, "metalIncome"); !ok {
			continue
		}
		fmt.Fprintf(w, "| %d |", minute)
		for _, c := range cols {
			band, _ := b.Band(minute, c)
			fmt.Fprintf(w, " %s (%s-%s) |", fmtNum(band.P50), fmtNum(band.P25), fmtNum(band.P75))
		}
		fmt.Fprintln(w)
	}

	fmt.Fprintln(w, "\n## What they build")
	for _, ph := range phases {
		var units, turrets []Build
		for _, g := range games {
			for _, bd := range g.Builds {
				if bd.Minute >= ph.from && bd.Minute < ph.to {
					if bd.Turret {
						turrets = append(turrets, bd)
					} else {
						units = append(units, bd)
					}
				}
			}
		}
		if len(units)+len(turrets) == 0 {
			continue
		}
		// per player still in the game at the phase's start
		n := 0.0
		for _, g := range games {
			for _, series := range g.Teams {
				if len(series) > 0 && series[len(series)-1].Minute > ph.from {
					n++
				}
			}
		}
		if n == 0 {
			continue
		}
		metal, air, t2 := 0.0, 0.0, 0.0
		for _, u := range units {
			metal += u.Cost
			if u.Air {
				air += u.Cost
			}
			if u.Tech >= 2 {
				t2 += u.Cost
			}
		}
		fmt.Fprintf(w, "\n### %s\n\n%.0f players still playing. Per player: %.0f combat units (%s metal) and %.1f turrets started; air %.0f%%, tech 2+ %.0f%% of the unit metal.\n\n",
			ph.label, n, float64(len(units))/n, fmtNum(metal/n), float64(len(turrets))/n, pct(air, metal), pct(t2, metal))
		fmt.Fprintf(w, "- Unit kinds by metal: %s\n", shares(units, func(b Build) string { return b.Kind }, 6))
		fmt.Fprintf(w, "- Most built: %s\n", shares(units, func(b Build) string { return b.Human }, 8))
		if len(turrets) > 0 {
			fmt.Fprintf(w, "- Turrets: %s\n", shares(turrets, func(b Build) string { return b.Human }, 6))
		}
	}

	fmt.Fprint(w, "\n## Timings\n\nMedian minute over the players who did it, and how many did.\n\n")
	timing := func(label string, pred func(Build) bool) {
		var mins []float64
		for _, g := range games {
			first := map[int]int{}
			for _, bd := range g.Builds {
				if pred(bd) {
					if m, ok := first[bd.Team]; !ok || bd.Minute < m {
						first[bd.Team] = bd.Minute
					}
				}
			}
			for _, m := range first {
				mins = append(mins, float64(m))
			}
		}
		if len(mins) == 0 {
			fmt.Fprintf(w, "- %s: nobody\n", label)
			return
		}
		fmt.Fprintf(w, "- %s: minute %s (%d of %d players)\n", label, fmtNum(median(mins)), len(mins), players)
	}
	timing("first combat unit", func(b Build) bool { return !b.Turret })
	timing("first turret", func(b Build) bool { return b.Turret })
	timing("first aircraft", func(b Build) bool { return !b.Turret && b.Air })
	timing("first tech 2 unit", func(b Build) bool { return !b.Turret && b.Tech >= 2 })
	timing("first anti-air (unit or turret)", func(b Build) bool { return b.Kind == "mobile anti-air" || b.Kind == "anti-air turret" })
}

func pct(part, whole float64) float64 {
	if whole == 0 {
		return 0
	}
	return 100 * part / whole
}

// shares lists the top groups by metal share, e.g. "raider 40%, assault 30%".
func shares(bs []Build, key func(Build) string, top int) string {
	by := map[string]float64{}
	total := 0.0
	for _, b := range bs {
		by[key(b)] += b.Cost
		total += b.Cost
	}
	type kv struct {
		k string
		v float64
	}
	var list []kv
	for k, v := range by {
		list = append(list, kv{k, v})
	}
	sort.Slice(list, func(i, j int) bool {
		if list[i].v != list[j].v {
			return list[i].v > list[j].v
		}
		return list[i].k < list[j].k
	})
	if len(list) > top {
		list = list[:top]
	}
	out := ""
	for i, e := range list {
		if i > 0 {
			out += ", "
		}
		out += fmt.Sprintf("%s %.0f%%", e.k, pct(e.v, total))
	}
	return out
}
